<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed } from 'vue';
const props = defineProps({ authorizations: Array, sites: Array, users: Array, stale_months: Number });
const form = useForm({ site_id: '', asset_id: '', user_id: '', granted_at: new Date().toISOString().slice(0,10), notes: '' });
const assets = computed(() => props.sites.find(site => site.id == form.site_id)?.assets || []);
const save = () => form.post(route('readiness.authorizations.store'), { preserveScroll: true, onSuccess: () => form.reset('user_id', 'asset_id', 'notes') });
const logDrill = (authorization) => { const notes = prompt('What was tested and what was learned?'); if (!notes) return; const duration = prompt('Duration in minutes (optional):'); router.post(route('readiness.drills.store', authorization.id), { drilled_at: new Date().toISOString().slice(0,10), duration_minutes: duration || null, participants: [authorization.user.name], notes }, { preserveScroll: true }); };
</script>
<template><Head title="Manual fallback readiness" /><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><h1 class="text-2xl font-semibold">Manual fallback readiness</h1><p class="text-sm text-slate-500">Who may take physical control, and when they last practiced.</p></div><Link :href="route('playbooks.index')" class="rounded-lg border px-4 py-2 text-sm font-semibold">Incident playbooks</Link></div></template><div class="mx-auto grid max-w-7xl gap-6 px-4 py-8 lg:grid-cols-[3fr_2fr]"><section class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="font-semibold">Authorization register</h2><div class="mt-4 divide-y"><div v-for="authorization in authorizations" :key="authorization.id" class="flex items-start justify-between gap-4 py-4"><div><div class="flex items-center gap-2"><p class="font-medium">{{ authorization.user.name }}</p><span v-if="authorization.is_stale" class="rounded-full bg-amber-100 px-2 py-0.5 text-xs font-semibold text-amber-800">Drill overdue</span><span v-else class="rounded-full bg-emerald-100 px-2 py-0.5 text-xs font-semibold text-emerald-800">Current</span></div><p class="mt-1 text-sm text-slate-600">{{ authorization.site.name }} / {{ authorization.asset?.name || 'Site-wide authorization' }}</p><p class="mt-1 text-xs text-slate-500">Granted {{ new Date(authorization.granted_at).toLocaleDateString() }} / Last drilled {{ authorization.last_drilled_at ? new Date(authorization.last_drilled_at).toLocaleDateString() : 'Never' }}</p></div><button @click="logDrill(authorization)" class="shrink-0 rounded-lg bg-teal-700 px-3 py-2 text-xs font-semibold text-white">Log drill</button></div><p v-if="!authorizations.length" class="py-10 text-center text-sm text-slate-500">No one is documented as authorized for manual operation yet.</p></div></section><form @submit.prevent="save" class="h-fit rounded-xl border bg-white p-6 shadow-sm"><h2 class="font-semibold">Grant authorization</h2><label class="mt-4 block text-sm font-medium">Person</label><select v-model="form.user_id" required class="mt-1 w-full rounded-lg border-slate-300"><option value="">Choose team member</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.name }}</option></select><label class="mt-3 block text-sm font-medium">Site</label><select v-model="form.site_id" required class="mt-1 w-full rounded-lg border-slate-300"><option value="">Choose site</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select><label class="mt-3 block text-sm font-medium">Asset (optional)</label><select v-model="form.asset_id" class="mt-1 w-full rounded-lg border-slate-300"><option value="">Entire site</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{ asset.name }}</option></select><label class="mt-3 block text-sm font-medium">Granted on</label><input v-model="form.granted_at" type="date" required class="mt-1 w-full rounded-lg border-slate-300" /><label class="mt-3 block text-sm font-medium">Conditions or notes</label><textarea v-model="form.notes" rows="3" class="mt-1 w-full rounded-lg border-slate-300"></textarea><button class="mt-4 w-full rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white">Record authorization</button></form></div></AuthenticatedLayout></template>
